import MarkdownIt from '/work/src/markdownit.ts'

const md = new MarkdownIt()

// patch in a variant of normalizeLink that logs
const orig = md.normalizeLink.bind(md)

// replicate normalizeLink with logging, in module context
import * as mdurl from 'mdurl'
import pc from 'punycode.js'

function normalizeLinkLogged(url, log) {
  const parsed = mdurl.parse(url, true)
  if (parsed.hostname) {
    if (!parsed.protocol || ['http:', 'https:', 'mailto:'].indexOf(parsed.protocol) > 0) {
      try {
        parsed.hostname = pc.toASCII(parsed.hostname)
        log('toASCII ok -> ' + parsed.hostname)
      } catch (er) {
        log('toASCII threw: ' + er.message)
      }
    }
  }
  if (parsed.auth) parsed.auth = mdurl.encode(parsed.auth)
  if (parsed.hostname) parsed.hostname = mdurl.encode(parsed.hostname)
  if (parsed.pathname) parsed.pathname = mdurl.encode(parsed.pathname)
  if (parsed.search) parsed.search = mdurl.encode(parsed.search)
  if (parsed.hash) parsed.hash = mdurl.encode(parsed.hash)
  return mdurl.format(parsed)
}

console.log('replicated:', normalizeLinkLogged('http://☃.net/', console.log))
console.log('actual    :', orig('http://☃.net/'))
